<?php
namespace App\Http\Controllers; use App\Models\{Berita,Umkm,DokumenDesa,Layanan,Lembaga}; use Illuminate\Http\Request; use Inertia\Inertia;
class PencarianController extends Controller { public function index(Request $r){$q=trim($r->q??'');$like='%'.$q.'%';return Inertia::render('Pencarian',['q'=>$q,'hasil'=>$q?['berita'=>Berita::published()->where('judul','like',$like)->limit(5)->get(['judul','slug']),'umkm'=>Umkm::aktif()->where('nama_usaha','like',$like)->limit(5)->get(['nama_usaha','id']),'dokumen'=>DokumenDesa::where('is_publik',true)->where('judul','like',$like)->limit(5)->get(['judul','file']),'layanan'=>Layanan::where('is_aktif',true)->where('nama','like',$like)->limit(5)->get(['nama']),'lembaga'=>Lembaga::where('aktif',true)->where('nama','like',$like)->limit(5)->get(['nama'])]:null]);} }
